import Foundation

/// t1281 (handbook §6#141, owner decision): what one payment REALLY takes from the wallet = amount + 0.1% protocol fee + network fee,
/// the same as the on-chain daily / term caps. The gateway counts every limit and every "spent" number with this formula
/// (gw src/v5/spend-cost.mjs); the app's local fallbacks ("used today", "this month") use this identical copy.
/// Cross-test: Tests/KipurseCoreTests/t1281-spend-cost.json.txt is generated by the gateway (scripts/t1281-spend-cost-fixture.mjs).
///   fee        = the row's fee, else ceil(amount * ppm / 1e6) (same rounding as the adapter)
///   networkFee = the row's network fee, else maxNetworkFee while the row is in flight (claimed / submitted), else 0 (finished rows)
public enum SpendCost {
  /// ceil(amount * ppm / 1_000_000) without overflow for any Int64 amount.
  public static func protocolFee(amount: Int64, ppm: Int64) -> Int64 {
    guard amount > 0, ppm > 0 else { return 0 }
    let q = amount / 1_000_000, r = amount % 1_000_000
    return q * ppm + (r * ppm + 999_999) / 1_000_000
  }
  /// Total cost of one payment record. `fee` / `networkFee` are the server's values (nil when the record has none).
  public static func cost(amount: Int64, fee: Int64?, networkFee: Int64?, ppm: Int64, inFlight: Bool = false, maxNetworkFee: Int64 = 0) -> Int64 {
    let a = max(0, amount)
    let f = fee.map { max(0, $0) } ?? protocolFee(amount: a, ppm: ppm)
    let n = networkFee.map { max(0, $0) } ?? (inFlight ? max(0, maxNetworkFee) : 0)
    return a + f + n
  }
  /// Server states that are still in flight (a missing network fee is then the owner's per-payment maximum).
  public static func inFlight(_ state: String) -> Bool { ["claimed", "submitted"].contains(state.lowercased()) }
}
